#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <ext/pb_ds/assoc_container.hpp>
using namespace std;
using namespace __gnu_pbds;

auto get_random_addr = [] { char *p = new char; delete p; return (uint64_t) p; };

struct HashFunction {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    uint64_t operator()(uint64_t x) const {
        static const uint64_t seed = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * (get_random_addr() | 1));
        return splitmix64(x ^ seed);
    }
};

const int MODULUS = 1e9 + 7;

struct ModNumber {
    int val;

    ModNumber(long long v = 0) {
        if (v < 0) v = v % MODULUS + MODULUS;
        if (v >= MODULUS) v %= MODULUS;
        val = v;
    }

    static int extended_gcd(int a, int m, int &x, int &y) {
        if (m == 0) {
            x = 1; y = 0;
            return a;
        }
        int g = extended_gcd(m, a % m, y, x);
        y -= (a / m) * x;
        return g;
    }

    static int inv(int a, int m = MODULUS) {
        int x, y;
        extended_gcd(a, m, x, y);
        return (x % m + m) % m;
    }

    explicit operator int() const { return val; }

    ModNumber& operator+=(const ModNumber &other) {
        val += other.val;
        if (val >= MODULUS) val -= MODULUS;
        return *this;
    }

    ModNumber& operator-=(const ModNumber &other) {
        val -= other.val;
        if (val < 0) val += MODULUS;
        return *this;
    }

    ModNumber& operator*=(const ModNumber &other) {
        val = (uint64_t(val) * other.val) % MODULUS;
        return *this;
    }

    ModNumber& operator/=(const ModNumber &other) {
        return *this *= ModNumber(inv(other.val));
    }

    friend ModNumber operator+(const ModNumber &a, const ModNumber &b) { return ModNumber(a) += b; }
    friend ModNumber operator-(const ModNumber &a, const ModNumber &b) { return ModNumber(a) -= b; }
    friend ModNumber operator*(const ModNumber &a, const ModNumber &b) { return ModNumber(a) *= b; }
    friend ModNumber operator/(const ModNumber &a, const ModNumber &b) { return ModNumber(a) /= b; }

    ModNumber pow(long long p) const {
        assert(p >= 0);
        ModNumber res = 1, base = *this;
        while (p > 0) {
            if (p & 1) res *= base;
            base *= base;
            p >>= 1;
        }
        return res;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<ModNumber>> prob(N, vector<ModNumber>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = ModNumber(p) / ModNumber(100);
        }

    vector<vector<int>> count_masks(N + 1);
    vector<int> index_lookup(1 << N, -1);
    for (int msk = 0; msk < (1 << N); ++msk) {
        int c = __builtin_popcount(msk);
        index_lookup[msk] = (int)count_masks[c].size();
        count_masks[c].push_back(msk);
    }

    gp_hash_table<long long, ModNumber, HashFunction> state_map;
    state_map[1LL << index_lookup[0]] = ModNumber(1);

    for (int left_idx = 0; left_idx < N; ++left_idx) {
        gp_hash_table<long long, ModNumber, HashFunction> new_state_map;
        vector<ModNumber> prod_mask(1 << N, ModNumber(1));
        for (int mask = 0; mask < (1 << N); ++mask) {
            for (int col = 0; col < N; ++col) {
                if (mask & (1 << col))
                    prod_mask[mask] *= prob[left_idx][col];
                else
                    prod_mask[mask] *= (ModNumber(1) - prob[left_idx][col]);
            }
        }

        vector<long long> new_bits(N, 0);
        vector<ModNumber> new_possible(1 << N, ModNumber(0));

        for (auto &entry : state_map) {
            long long mask_state = entry.first;
            ModNumber prob_state = entry.second;
            fill(new_bits.begin(), new_bits.end(), 0);
            for (int m : count_masks[left_idx]) {
                if ((mask_state >> index_lookup[m]) & 1) {
                    for (int i = 0; i < N; ++i) {
                        if (((m >> i) & 1) == 0) {
                            new_bits[i] |= 1LL << index_lookup[m | (1 << i)];
                        }
                    }
                }
            }
            fill(new_possible.begin(), new_possible.end(), ModNumber(0));
            for (int current_mask = 1; current_mask < (1 << N); ++current_mask) {
                int ctz = __builtin_ctz(current_mask);
                new_possible[current_mask] = new_possible[current_mask & (current_mask - 1)] | new_bits[ctz];
                long long combined_mask = new_possible[current_mask];
                new_state_map[combined_mask] += prob_state * prod_mask[current_mask];
            }
        }
        state_map = move(new_state_map);
    }

    ModNumber total = 0;
    for (auto &entry : state_map) {
        if (((entry.first >> index_lookup[(1 << N) - 1]) & 1) != 0)
            total += entry.second;
    }
    cout << (int)total << '\n';
}
